import { Locator, Page, expect } from '@playwright/test';
import BasePage from '../Framework/src/pages/base.page';
import { HTMLSubStepLogger } from '../Framework/src/utils/htmlSubStepLogger';

/** Confirmed live: Tax column is consistently 8.5% of (Lodging + Harvest + Add-ons) across sampled rows. */
export const INVOICE_TAX_RATE = 0.085;

export class InvoicePage extends BasePage {
  constructor(page: Page, subStepLogger?: HTMLSubStepLogger) {
    super(page, subStepLogger);
  }

  // ==================== Locators ====================

  get pageHeading(): Locator {
    return this.page.getByRole('heading', { name: 'Invoices' });
  }

  get generateNewInvoiceButton(): Locator {
    return this.page.getByRole('button', { name: 'Generate new Invoice' });
  }

  get searchInput(): Locator {
    return this.page.getByRole('textbox', { name: /search/i });
  }

  get cardViewButton(): Locator {
    return this.page.getByRole('button', { name: 'Card view' });
  }

  get tableViewButton(): Locator {
    return this.page.getByRole('button', { name: 'Table view' });
  }

  get invoiceTable(): Locator {
    return this.page.getByRole('table');
  }

  getInvoiceRowByBooking(bookingId: string): Locator {
    return this.invoiceTable.getByRole('row').filter({ hasText: bookingId });
  }

  rowMoreOptionsButton(bookingId: string): Locator {
    return this.getInvoiceRowByBooking(bookingId).getByRole('button', { name: 'More options' });
  }

  rowTaxCell(bookingId: string): Locator {
    return this.getInvoiceRowByBooking(bookingId).locator('td').nth(7);
  }

  rowTotalCell(bookingId: string): Locator {
    return this.getInvoiceRowByBooking(bookingId).locator('td').nth(8);
  }

  rowInvoicedBadge(bookingId: string): Locator {
    return this.getInvoiceRowByBooking(bookingId).getByText(/Invoiced/i);
  }

  // --- Generate Invoice page ---

  get bookingTab(): Locator {
    return this.page.getByRole('tab', { name: 'Booking' });
  }

  get harvestsWithoutBookingTab(): Locator {
    return this.page.getByRole('tab', { name: 'Harvests without booking' });
  }

  get selectBookingList(): Locator {
    return this.page.getByTestId('select-booking-list').or(this.page.getByRole('list', { name: /select booking/i }));
  }

  selectBookingListItem(bookingId: string): Locator {
    return this.selectBookingList.getByText(bookingId);
  }

  get invoicePreviewPanel(): Locator {
    return this.page.getByTestId('invoice-preview').or(this.page.getByText(/invoice preview/i).locator('..'));
  }

  get invoicePreviewEmptyState(): Locator {
    return this.invoicePreviewPanel.getByText(/select a booking|no booking selected|nothing selected/i);
  }

  get previewBookingIdField(): Locator {
    return this.invoicePreviewPanel.getByText(/Booking ID/i).locator('..');
  }

  get previewRanchField(): Locator {
    return this.invoicePreviewPanel.getByText(/^Ranch/i).locator('..');
  }

  get previewCheckInOutField(): Locator {
    return this.invoicePreviewPanel.getByText(/Check-?in/i).locator('..');
  }

  get previewDurationField(): Locator {
    return this.invoicePreviewPanel.getByText(/Duration/i).locator('..');
  }

  get previewBillToField(): Locator {
    return this.invoicePreviewPanel.getByText(/Bill To/i).locator('..');
  }

  get previewChargesList(): Locator {
    return this.invoicePreviewPanel.getByTestId('invoice-charges-list').or(this.invoicePreviewPanel.getByRole('list'));
  }

  get previewTaxField(): Locator {
    return this.invoicePreviewPanel.getByText(/^Tax/i).locator('..');
  }

  get previewTotalField(): Locator {
    return this.invoicePreviewPanel.getByText(/^Total/i).locator('..');
  }

  get generateInvoiceButton(): Locator {
    return this.page.getByRole('button', { name: 'Generate Invoice' });
  }

  // --- Invoice detail view ---

  get downloadPdfButton(): Locator {
    return this.page.getByRole('button', { name: 'Download PDF' });
  }

  get downloadExcelButton(): Locator {
    return this.page.getByRole('button', { name: 'Download Excel' });
  }

  get deleteDiscardButton(): Locator {
    return this.page.getByRole('button', { name: /Delete|Discard/i });
  }

  get confirmationDialog(): Locator {
    return this.page.getByRole('dialog');
  }

  get confirmationDialogCancelButton(): Locator {
    return this.confirmationDialog.getByRole('button', { name: 'Cancel' });
  }

  get confirmationDialogConfirmButton(): Locator {
    return this.confirmationDialog.getByRole('button', { name: /Delete|Discard|Confirm/i });
  }

  // ==================== Validations ====================

  async assertPageLoaded(): Promise<void> {
    await expect(this.pageHeading).toBeVisible();
    await expect(this.generateNewInvoiceButton).toBeVisible();
  }

  async assertRowInvoiced(bookingId: string, invoiceNumber: string): Promise<void> {
    await expect(this.rowInvoicedBadge(bookingId)).toContainText(invoiceNumber);
  }

  async assertRowNotSelectable(bookingId: string): Promise<void> {
    await expect(this.selectBookingListItem(bookingId)).toHaveAttribute('aria-disabled', 'true');
  }

  async assertRowSelectable(bookingId: string): Promise<void> {
    await expect(this.selectBookingListItem(bookingId)).not.toHaveAttribute('aria-disabled', 'true');
  }

  async assertPreviewEmptyState(): Promise<void> {
    await expect(this.invoicePreviewEmptyState).toBeVisible();
  }

  async assertDurationDisplayed(expectedText: string): Promise<void> {
    await expect(this.previewDurationField).toContainText(expectedText);
  }

  async assertTotalMatchesTaxFormula(subtotal: number, expectedTotal: number): Promise<void> {
    const computedTax = Math.round(subtotal * INVOICE_TAX_RATE * 100) / 100;
    const computedTotal = Math.round((subtotal + computedTax) * 100) / 100;
    expect(computedTotal).toBeCloseTo(expectedTotal, 2);
    await expect(this.previewTotalField).toContainText(expectedTotal.toFixed(2));
  }

  async assertDownloadControlsVisible(): Promise<void> {
    await expect(this.downloadPdfButton).toBeVisible();
    await expect(this.downloadExcelButton).toBeVisible();
  }

  async assertConfirmationDialogOpen(): Promise<void> {
    await expect(this.confirmationDialog).toBeVisible();
  }

  async assertConfirmationDialogClosed(): Promise<void> {
    await expect(this.confirmationDialog).toBeHidden();
  }

  async assertActiveTab(tabName: 'Booking' | 'Harvests without booking'): Promise<void> {
    const tab = tabName === 'Booking' ? this.bookingTab : this.harvestsWithoutBookingTab;
    await expect(tab).toHaveAttribute('aria-selected', 'true');
  }

  // ==================== Actions ====================

  async navigateToInvoicesList(): Promise<void> {
    await this.withHeal(this.page.getByRole('link', { name: 'Invoices' }), (l) => l.click(), 'Invoices Nav Link');
    await this.waitForLoadingToComplete();
  }

  async clickGenerateNewInvoice(): Promise<void> {
    await this.logInfo('Opening Generate Invoice page');
    await this.withHeal(this.generateNewInvoiceButton, (l) => l.click(), 'Generate New Invoice Button');
  }

  async switchToTab(tabName: 'Booking' | 'Harvests without booking'): Promise<void> {
    const tab = tabName === 'Booking' ? this.bookingTab : this.harvestsWithoutBookingTab;
    await this.withHeal(tab, (l) => l.click(), `${tabName} Tab`);
  }

  async selectBookingForInvoice(bookingId: string): Promise<void> {
    await this.logInfo(`Selecting booking ${bookingId} for invoicing`);
    await this.withHeal(this.selectBookingListItem(bookingId), (l) => l.click(), `Select Booking ${bookingId}`);
  }

  async clickGenerateInvoice(): Promise<void> {
    await this.withHeal(this.generateInvoiceButton, (l) => l.click(), 'Generate Invoice Button');
    await this.logSuccess('Invoice generation submitted');
  }

  async generateInvoiceForBooking(bookingId: string): Promise<void> {
    await this.clickGenerateNewInvoice();
    await this.switchToTab('Booking');
    await this.selectBookingForInvoice(bookingId);
    await this.clickGenerateInvoice();
  }

  async searchInvoices(term: string): Promise<void> {
    await this.withHeal(this.searchInput, (l) => l.fill(term), 'Invoice Search Box');
  }

  async openInvoiceRowActions(bookingId: string): Promise<void> {
    await this.withHeal(this.rowMoreOptionsButton(bookingId), (l) => l.click(), 'Invoice Row More Options');
  }

  async downloadPdf(): Promise<void> {
    const [download] = await Promise.all([
      this.page.waitForEvent('download'),
      this.withHeal(this.downloadPdfButton, (l) => l.click(), 'Download PDF Button'),
    ]);
    await this.logSuccess(`PDF download triggered: ${download.suggestedFilename()}`);
  }

  async downloadExcel(): Promise<void> {
    const [download] = await Promise.all([
      this.page.waitForEvent('download'),
      this.withHeal(this.downloadExcelButton, (l) => l.click(), 'Download Excel Button'),
    ]);
    await this.logSuccess(`Excel download triggered: ${download.suggestedFilename()}`);
  }

  async deleteInvoice(): Promise<void> {
    await this.withHeal(this.deleteDiscardButton, (l) => l.click(), 'Delete/Discard Invoice Button');
  }

  async confirmDeleteInvoice(): Promise<void> {
    await this.withHeal(this.confirmationDialogConfirmButton, (l) => l.click(), 'Confirm Delete Button');
    await this.logSuccess('Invoice discarded');
  }

  async cancelDeleteInvoice(): Promise<void> {
    await this.withHeal(this.confirmationDialogCancelButton, (l) => l.click(), 'Cancel Delete Button');
  }
}
